pub struct OpenOptions {
    pub ram_bytes: u64, pub threads: usize /* default available_parallelism()/2, min 1 */,
    pub device: Device /* Auto|Cpu|Gpu (doc re-embedding; queries always CPU) */,
    pub max_concurrent: usize /* fast 4, compact 2 */, pub queue_timeout: Option<Duration>,
    pub preload: Preload /* Models|All|None */, pub require_semantic: bool,
    pub ov_libs: Option<PathBuf>, pub models_dir: Option<PathBuf> /* dev layout */,
    pub cache_dir: Option<PathBuf> /* L2, None=off */, pub cache_disk_bytes: u64, pub self_test: bool,
}
#[derive(Clone)] pub struct Archive(Arc<Inner>);              // Send + Sync
impl Archive {
    pub fn open(path: &Path, o: &OpenOptions) -> Result<Archive, HnzError>;
    pub fn inspect(path: &Path) -> Result<BlockInfo, HnzError>;   // no models loaded
    pub fn search(&self, r: &SearchRequest, c: &CancelToken) -> Result<SearchResponse, HnzError>;
    pub fn get_many(&self, ids: &[u32], text: TextMode, timeout: Option<Duration>, c: &CancelToken) -> Result<Vec<Option<ItemOut>>, HnzError>;
    pub fn embed(&self, texts: &[String], kind: EmbedKind) -> Result<Vec<Vec<f32>>, HnzError>;
    pub fn stats(&self) -> Stats;                                  // Serialize
    pub fn shutdown(&self, wait: Duration) -> Result<(), HnzError>; // idempotent; cancels in-flight work after `wait`
}
#[derive(Deserialize)] #[serde(deny_unknown_fields, default)]
pub struct SearchRequest { pub query: String, pub k: usize, pub offset: usize, pub since: Option<DateArg>, pub until: Option<DateArg>,
    pub types: Vec<String>, pub author: Option<String>, pub mode: Mode, pub text: TextMode, pub include_dead: bool,
    pub thread_context: bool, pub rerank: Rerank, pub candidates: Option<usize>, pub timeout_ms: Option<u64>,
    pub explain: bool, pub w_bm25: f32, pub c_bm25: f32 }
#[derive(Deserialize)] #[serde(untagged)] pub enum DateArg { Text(String) /* inclusive period, dates::parse */, Epoch(i64) /* exact instant */ }
pub enum TextMode { None, Title, Snippet, Full }   pub enum Rerank { Auto, Exact, Off }
#[derive(Serialize)] pub struct SearchResponse { pub query: String, pub profile: &'static str, pub hits: Vec<ResultItem /* existing struct */>, pub timings_ms: Timings, pub warnings: Vec<String> }
#[derive(Serialize, Default)] pub struct Timings { pub queue: f32, pub embed: f32, pub search: f32, pub rerank: f32, pub fetch: f32, pub total: f32 }
#[derive(Clone, Default)] pub struct CancelToken(Arc<AtomicBool>);   // also fired by deadlines
#[derive(thiserror::Error, Debug)] pub enum HnzError { NotFound(PathBuf), Incompatible{what:String,block:String,supported:String,hint:String},
    Corrupt{component:String,detail:String}, RuntimeMissing(String), Budget{required:u64,budget:u64,detail:String},
    InvalidQuery(String), Busy, Timeout, Cancelled, Closed, Internal(String) }
