### PyO3 binding (py/src/lib.rs)
```rust
#[pyclass(frozen, module="hnz._hnz", name="Archive")] struct PyArchive { inner: parking_lot::RwLock<Option<api::Archive>> }
#[pymethods] impl PyArchive {
  #[staticmethod] fn open(py: Python<'_>, path: PathBuf, opts: Bound<'_, PyDict>) -> PyResult<Self>;       // detach during open
  fn search<'py>(&self, py: Python<'py>, req: Bound<'py, PyDict>, cancel: Option<PyRef<'py, PyCancelToken>>) -> PyResult<Bound<'py, PyAny>>;
  fn get_many<'py>(&self, py: Python<'py>, ids: Vec<u32>, text: &str, timeout: Option<f64>) -> PyResult<Bound<'py, PyAny>>;
  fn embed(&self, py: Python<'_>, texts: Vec<String>, kind: &str) -> PyResult<Vec<Vec<f32>>>;
  fn stats<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>>;
  fn close(&self, py: Python<'_>, timeout: f64) -> PyResult<()>;   // take() under the write lock, then detach + shutdown
}
// body pattern: let a = self.live()?; let r = py.detach(move || guard(|| a.search(&req, &tok)))?; pythonize(py, &r)
fn guard<T>(f: impl FnOnce() -> Result<T, HnzError>) -> PyResult<T>;   // catch_unwind + map to python/hnz/errors.py classes
#[pymodule] fn _hnz(m): __version__, FORMAT_VERSION=(2,0), MATH_VERSIONS=(2,), Archive, CancelToken, inspect, serve, build_info()
```
