pub enum Quality { Fast, Balanced, Precise, Custom { k_vec: usize, k_lex: usize, prefix_body_tokens: u32 } }
pub enum TextMode { None, Snippet, Full }
pub struct SearchRequest { pub text: String, pub k: usize, pub from: Option<i64>, pub to: Option<i64>, pub types: Vec<u8>,
  pub by: Option<String>, pub include_dead: bool, pub mode: Mode, pub quality: Quality, pub deadline: Duration,
  pub text_mode: TextMode, pub w: Option<f32>, pub c: Option<f32> }
pub struct SearchResponse { pub results: Vec<ResultItem /* + reranked: bool */>, pub candidates: usize, pub reranked: usize,
  pub cache_hits: usize, pub degraded: bool, pub timings: Timings /* embed, scan, lex, decode, reembed, fuse, fetch, total */ }
impl CompactEngine {   // Send + Sync
  pub fn open(path: &Path, o: OpenOpts) -> Result<Arc<Self>>;
  pub fn search(&self, r: &SearchRequest) -> Result<SearchResponse>;
  pub fn search_progressive(&self, r: &SearchRequest, on_preview: &mut dyn FnMut(&SearchResponse)) -> Result<SearchResponse>;
  pub fn get(&self, id: u32, t: TextMode) -> Result<Option<Item>>;
  pub fn stats(&self) -> EngineStats;   // RAM per component, cache hit rates, decoder queue
}
